document.addEventListener("DOMContentLoaded", function () {
    const getTxId = () => "tx-" + Date.now() + "-" + Math.floor(Math.random() * 100000);

    // Helper para tracking de clics
    const trackClick = (selector, eventData) => {
        document.querySelectorAll(selector).forEach(el => {
            el.addEventListener("click", () => gtag("event", "conversion", eventData));
        });
    };

    trackClick('a[href*="wa.link"], a[href*="wa.me"]', { 'send_to': 'AW-950025686/G5d9COv-gYABENb7gMUD' });
    trackClick('a[href^="tel:"]', { 'send_to': 'AW-950025686/7f5OCLWNlYABENb7gMUD', 'value': 200, 'currency': 'ARS', 'transaction_id': getTxId() });
    trackClick('.btn-reserve', { 'send_to': 'AW-950025686/JX0xCOX-gYABENb7gMUD', 'value': 10, 'currency': 'ARS', 'transaction_id': getTxId() });

    // Lazy Load HubSpot
    const loadHS = () => {
        const script = document.createElement("script");
        script.src = "https://js.hsforms.net/forms/embed/50609640.js";
        script.defer = true;
        script.onerror = () => {
            const frame = document.querySelector(".hs-form-frame");
            if (frame) {
                frame.innerHTML = '<div class="text-center p-4"><h5>Error de carga</h5><button id="hs-retry" class="btn btn-outline-primary btn-sm">Reintentar</button></div>';
                document.getElementById("hs-retry").onclick = loadHS;
            }
        };
        document.body.appendChild(script);
    };

    const observer = new IntersectionObserver(entries => {
        if (entries[0].isIntersecting) {
            loadHS();
            observer.disconnect();
        }
    }, { rootMargin: "200px" });

    const contactSection = document.getElementById("contacto");
    if (contactSection) observer.observe(contactSection);

    window.addEventListener("message", function (event) {
        if (event.data.type === 'hsFormCallback' && event.data.eventName === 'onFormSubmitted') {
            gtag('event', 'conversion', { 'send_to': 'AW-950025686/GSNXCJ-IrKMBENb7gMUD', 'value': 150, 'currency': 'ARS', 'transaction_id': getTxId() });
        }
    });
});